    enum CodingKeys: String, CodingKey {
        case headers
        case issues
        case comments
        case labels
        case repoUrl = "repo_url"
    }
}

/// An issue as returned to the frontend/scripts.
public struct IssueView: Codable, Sendable, Equatable {
    public var id: String
    public var title: String
    public var summary: String
    public var impact: String
    public var repro: String
    public var resolutionCriteria: String
    /// One of Open, In progress, Blocked, Done.
    public var status: String
    /// One of low, medium, high, urgent.
    public var priority: String
    /// Free text; null when unassigned.
    public var assignee: String?
    /// Sorted.
    public var labels: [String]
    /// The creator's account id (64 hex).
    public var createdBy: String
    /// Unix milliseconds.
    public var createdAt: UInt64

    public init(id: String, title: String, summary: String, impact: String, repro: String, resolutionCriteria: String, status: String, priority: String, assignee: String? = nil, labels: [String], createdBy: String, createdAt: UInt64) {
        self.id = id
        self.title = title
        self.summary = summary
        self.impact = impact
        self.repro = repro
        self.resolutionCriteria = resolutionCriteria
        self.status = status
        self.priority = priority
        self.assignee = assignee
        self.labels = labels
        self.createdBy = createdBy
        self.createdAt = createdAt
    }

    enum CodingKeys: String, CodingKey {
        case id
        case title
        case summary
        case impact
        case repro
        case resolutionCriteria = "resolution_criteria"
        case status
        case priority
        case assignee
        case labels
        case createdBy = "created_by"
        case createdAt = "created_at"
    }
}

/// One label on one issue.
public struct LabelTag: Codable, Sendable, Equatable {
    public var issueId: String
    public var label: String
    public var addedAt: UInt64

    public init(issueId: String, label: String, addedAt: UInt64) {
        self.issueId = issueId
        self.label = label
        self.addedAt = addedAt
    }

    enum CodingKeys: String, CodingKey {
        case issueId = "issue_id"
        case label
        case addedAt = "added_at"
    }
}

/// This context's repository metadata. `repo_url` is empty until `set_repo_url`.
public struct RepoInfo: Codable, Sendable, Equatable {
    public var repoUrl: String

    public init(repoUrl: String) {
        self.repoUrl = repoUrl
    }

    enum CodingKeys: String, CodingKey {
        case repoUrl = "repo_url"
    }
}

/// One board column's live count (named struct — never a `(String, u64)` tuple).
public struct StatusCount: Codable, Sendable, Equatable {
    /// One of Open, In progress, Blocked, Done.
    public var status: String
    public var count: UInt64

    public init(status: String, count: UInt64) {
        self.status = status
        self.count = count
    }
}
